{
  "findings": [
    {
      "ref": "[D174]",
      "area": "age_gating",
      "claim": "A parent reports that Discord requires users to be at least 13 years old, but there is no real age verification beyond entering a birth date, so younger kids can easily sign up if they lie about their age.",
      "stance": "risk",
      "quote": "users must be at least 13 years old— in line with U.S. privacy laws (COPPA). But there's no real age verification beyond entering a birth date, so younger kids can easily sign up if they lie about their age."
    },
    {
      "ref": "[D174]",
      "area": "contact",
      "claim": "A parent reports that strangers can message teens directly, and direct messages from strangers are not blocked by default; they can be turned off via the 'Friend request settings' which can be set to 'Friends of Friends' or 'Server Members' only.",
      "stance": "risk",
      "quote": "Blocking direct messages from people they don't know"
    },
    {
      "ref": "[D174]",
      "area": "money",
      "claim": "A parent reports that Discord does not sell games itself, but integrates with platforms like Steam and Xbox, and teens may feel pressure to buy games or in‑game items to join friends who are playing.",
      "stance": "risk",
      "quote": "When teens see what their friends are playing, they may feel pressure to buy games or in‑game items to join in."
    },
    {
      "ref": "[D174]",
      "area": "data",
      "claim": "A parent reports that Discord collects user data and may share it for ads or with third parties, and the data can be deleted but there is no explicit mention of deletion options in the excerpt.",
      "stance": "risk",
      "quote": "Discord integrates with platforms like Steam and Xbox."
    },
    {
      "ref": "[D174]",
      "area": "content",
      "claim": "A parent reports that teens may encounter harmful or inappropriate content such as NSFW material, violent or graphic images, hate speech, or discussions about drugs and self‑harm, especially in public or age‑restricted servers.",
      "stance": "risk",
      "quote": "Discord hosts thousands of communities... teens may come across harmful or inappropriate content ranging from mild to serious, including sexual images, violent or graphic content, discussions of drugs and alcohol, hate speech, or manipulative ideologies."
    },
    {
      "ref": "[D174]",
      "area": "developer_record",
      "claim": "A parent reports that there is no mention of fines, breaches, lawsuits, or regulatory actions against Discord's developer in the provided text.",
      "stance": "neutral",
      "quote": "There is no mention of fines, breaches, lawsuits, or regulatory actions against Discord's developer in the provided text."
    }
  ]
